"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatDashboardValue, orderRanked, type DashboardFormat } from "@/lib/dashboard-format"

export type RankedBarItem = {
  id: string
  label: string
  value: number
  meta?: string
  /** Override the computed share (0–1). */
  share?: number
}

export type RankedBarsClassNames = {
  root?: string
  item?: string
  label?: string
  bar?: string
  value?: string
}

export type RankedBarsProps = {
  items: readonly RankedBarItem[]
  label?: string
  valueFormat?: DashboardFormat
  locale?: string
  currency?: string
  showPercent?: boolean
  max?: number
  highlight?: "first" | "none" | string
  sort?: "asc" | "desc" | "none"
  limit?: number
  moreLabel?: string
  lessLabel?: string
  onSelect?: (item: RankedBarItem) => void
  className?: string
  classNames?: RankedBarsClassNames
}

export function RankedBars({
  items,
  label = "Ranked values",
  valueFormat = "number",
  locale = "en-US",
  currency = "USD",
  showPercent,
  max,
  highlight = "first",
  sort = "desc",
  limit,
  moreLabel = "Show all",
  lessLabel = "Show less",
  onSelect,
  className,
  classNames,
  layout = "stacked",
}: RankedBarsProps & { layout?: "stacked" | "inline" }) {
  const [expanded, setExpanded] = React.useState(false)
  const ordered = orderRanked(items, sort)
  const visible = limit != null && !expanded ? ordered.slice(0, limit) : ordered
  const peak = max ?? Math.max(...ordered.map((item) => item.value), 0)
  const percentOn = showPercent ?? ordered.some((item) => item.share != null)

  return (
    <div data-slot="ranked-bars" className={cn("min-w-0", className, classNames?.root)}>
      <ol aria-label={label} className="flex flex-col gap-3">
        {visible.map((item, index) => {
          const ratio = peak > 0 ? Math.min(1, item.value / peak) : 0
          const emphasized = highlight === "first" ? index === 0 : highlight !== "none" && highlight === item.id
          const value = formatDashboardValue(item.value, valueFormat, locale, currency)
          const percent = formatDashboardValue(item.share ?? 0, "percent", locale)
          const summary = [item.label, item.meta, value, percentOn ? percent : null].filter(Boolean).join(", ")
          const bar = (
            <span className="block h-2 overflow-hidden rounded-full bg-muted" aria-hidden>
              <span
                data-slot="ranked-bar-fill"
                className={cn(
                  "block h-full origin-left rounded-full motion-reduce:transition-none",
                  emphasized ? "bg-primary" : "bg-chart-3",
                  classNames?.bar,
                )}
                style={{ transform: `scaleX(${Math.max(ratio, 0.02)})` }}
              />
            </span>
          )
          const labelNode = (
            <span className={cn("min-w-0 truncate text-sm font-medium", classNames?.label)}>{item.label}</span>
          )
          const valueNode = (
            <span className={cn("inline-flex shrink-0 items-baseline gap-2 text-sm tabular-nums", classNames?.value)}>
              {item.meta ? <span className="text-muted-foreground">{item.meta} </span> : null}
              {percentOn ? <span className="font-medium">{percent}</span> : <span>{value}</span>}
            </span>
          )
          const inner =
            layout === "inline" ? (
              <span className="grid min-w-0 grid-cols-[minmax(0,35%)_minmax(0,1fr)_auto] items-center gap-3">
                {labelNode}
                {bar}
                {valueNode}
              </span>
            ) : (
              <span className="flex min-w-0 flex-col gap-1.5">
                <span className="flex min-w-0 items-baseline justify-between gap-3">
                  {labelNode}
                  {valueNode}
                </span>
                {bar}
              </span>
            )
          return (
            <li key={item.id} data-rank={index + 1}>
              {onSelect ? (
                <button
                  type="button"
                  className={cn(
                    "w-full rounded-lg text-start focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    classNames?.item,
                  )}
                  aria-label={summary}
                  onClick={() => onSelect(item)}
                >
                  {inner}
                </button>
              ) : (
                <div className={classNames?.item} aria-label={summary}>
                  {inner}
                </div>
              )}
            </li>
          )
        })}
      </ol>
      {limit != null && ordered.length > limit ? (
        <button type="button" className="mt-3 text-sm text-muted-foreground underline-offset-2 hover:underline" onClick={() => setExpanded((value) => !value)}>
          {expanded ? lessLabel : moreLabel}
        </button>
      ) : null}
    </div>
  )
}

/** Number, date, and greeting helpers for dashboard pieces. No theme tokens. */

export type DashboardFormat = "number" | "currency" | "percent" | "compact" | "text" | "points"

export function formatDashboardValue(
  value: number | string,
  format: DashboardFormat = "text",
  locale = "en-US",
  currency = "USD",
): string {
  if (typeof value !== "number" || !Number.isFinite(value) || format === "text") return String(value)
  if (format === "currency") {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: Math.abs(value) >= 10000 ? "compact" : "standard",
      maximumFractionDigits: Math.abs(value) >= 10000 ? 1 : 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === "compact") {
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
  }
  if (format === "points") {
    const formatted = new Intl.NumberFormat(locale, {
      signDisplay: "exceptZero",
      maximumFractionDigits: 1,
    }).format(value)
    return `${formatted} pts`
  }
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatDashboardDate(
  value: string | number | Date,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" },
): string {
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return new Intl.DateTimeFormat(locale, options).format(date)
}

export function joinMeta(parts: Array<string | number | null | undefined | false>): string {
  return parts.filter((part) => part != null && part !== false && part !== "").map(String).join(" · ")
}

const DAY_PART = {
  en: { morning: "Good morning", afternoon: "Good afternoon", evening: "Good evening" },
  es: { morning: "Buenos días", afternoon: "Buenas tardes", evening: "Buenas noches" },
} as const

/** Time-of-day greeting. Spanish locales use es; everything else uses en. */
export function greeting(date: Date, locale: string, name: string): string {
  const hour = date.getHours()
  const part = hour < 12 ? "morning" : hour < 18 ? "afternoon" : "evening"
  const table = locale.toLowerCase().startsWith("es") ? DAY_PART.es : DAY_PART.en
  return `${table[part]}, ${name}`
}

export function shareOf(value: number, total: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(total) || total <= 0) return 0
  return value / total
}

export function clampRatio(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export type RankedInput = { id: string; value: number; share?: number }

export function orderRanked<T extends RankedInput>(items: readonly T[], sort: "asc" | "desc" | "none" = "desc"): T[] {
  const copy = items.map((item) => ({ ...item }))
  if (sort === "asc") copy.sort((a, b) => a.value - b.value || a.id.localeCompare(b.id))
  if (sort === "desc") copy.sort((a, b) => b.value - a.value || a.id.localeCompare(b.id))
  const total = copy.reduce((sum, item) => sum + (Number.isFinite(item.value) ? item.value : 0), 0)
  return copy.map((item) => ({ ...item, share: item.share ?? shareOf(item.value, total) }))
}

/** Delay in seconds for a short opacity stagger. Zero when motion is reduced. */
export function staggerDelay(index: number, reduced: boolean, step = 0.04): number {
  if (reduced || index <= 0) return 0
  return index * step
}
